using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tool that fetches data from an external API.
/// HttpClient is injected via DI through IHttpClientFactory.
/// </summary>
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from the external API for a given resource path.")]
    public static async Task<string> FetchApiData(
        IHttpClientFactory httpClientFactory,
        [Description("The API resource path to query, e.g. \"/users/1\".")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

/// <summary>
/// MCP prompt template for text summarization.
/// </summary>
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize text.")]
    public static IList<ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points.")] string style = "brief")
    {
        return
        [
            new ChatMessage(
                ChatMessageRole.User,
                $$"""
                Summarize the following text using a {{style}} style.
                Return only the summary, no preamble.

                ---
                {{text}}
                ---
                """)
        ];
    }
}

